    mov.u32 r_ky, 0;
KY_LOAD_LOOP:
    setp.ge.u32 p5, r_ky, rK;
    @p5 bra KY_LOAD_DONE;
    // y coordinate and predicate for this ky
    cvt.s32.u32 s_y, r_ky;
    add.s32 s_y, s_y_base, s_y;
    setp.ge.s32 py0, s_y, 0;
    setp.lt.s32 py1, s_y, rH;
    and.pred py_ok, py0, py1;
    and.pred p_yz_ok, pz_ok, py_ok;
