    mul.lo.u32 r_tmp2, r_n, rCin;
    add.u32    r_tmp2, r_tmp2, r_ic;
    mul.lo.u32 r_tmp2, r_tmp2, rD;
    add.u32    r_tmp2, r_tmp2, ru_sz;
