LEFT_STORE_ZERO_ROW:
    mul.wide.u32 addr_s, r_t, 4;
    add.u64     addr_s, addr_plane, addr_s;
    st.shared.f32 [addr_s], 0f00000000;
LEFT_STORE_DONE_ROW:
