    mul.wide.u32 addr_sw, r_tmp1, 4;
    add.u64     addr_sw, w_sh_ptr, addr_sw;
    ld.shared.f32 wval2, [addr_sw];
    // load w[kx+1]
    add.u32     r_tmp2, r_tmp1, 1;
    mul.wide.u32 addr_sw, r_tmp2, 4;
    add.u64     addr_sw, w_sh_ptr, addr_sw;
    ld.shared.f32 wval, [addr_sw];
    // x indices in shared for (2*tid + kx) .. use vectorized loads
    add.u32 r_tmp2, r_tw2, r_kx;                // base = 2*tid + kx
    mul.wide.u32 addr_sx, r_tmp2, 4;
    add.u64     addr_sx, addr_plane, addr_sx;
    ld.shared.v2.f32 {vx0, vx1}, [addr_sx];     // x0, x1
    add.u32 r_tmp4, r_tmp2, 2;
    mul.wide.u32 addr_sx, r_tmp4, 4;
    add.u64     addr_sx, addr_plane, addr_sx;
    ld.shared.v2.f32 {vx2, vx3}, [addr_sx];     // x2, x3
    // accumulate for two outputs
    fma.rn.f32 acc,  vx0, wval2, acc;           // out0 += x0 * w[kx]
    fma.rn.f32 acc1, vx1, wval2, acc1;          // out1 += x1 * w[kx]
    fma.rn.f32 acc,  vx1, wval,  acc;           // out0 += x1 * w[kx+1]
    fma.rn.f32 acc1, vx2, wval,  acc1;          // out1 += x2 * w[kx+1]
    // advance kx by 2
    add.u32 r_kx, r_kx, 2;
    bra KX_PAIR_LOOP;
KX_TAIL_LOOP:
    // handle tail element if K is odd
    setp.ge.u32 p7, r_kx, rK;
    @p7 bra KX_COMP_DONE;
    // w index in shared: (ky*K + kx)
    mul.lo.u32 r_tmp1, r_ky, rK;
    add.u32    r_tmp1, r_tmp1, r_kx;
    mul.wide.u32 addr_sw, r_tmp1, 4;
    add.u64     addr_sw, w_sh_ptr, addr_sw;
    ld.shared.f32 wval2, [addr_sw];
    // x indices in shared: 2*tid + kx (vector load gives x0,x1)
    add.u32 r_tmp2, r_tw2, r_kx;
    mul.wide.u32 addr_sx, r_tmp2, 4;
    add.u64     addr_sx, addr_plane, addr_sx;
    ld.shared.v2.f32 {vx0, vx1}, [addr_sx];
    fma.rn.f32 acc,  vx0, wval2, acc;
    fma.rn.f32 acc1, vx1, wval2, acc1;
KX_COMP_DONE:
    add.u32 r_ky, r_ky, 1;
    bra KY_COMP_LOOP;
KY_COMP_DONE:
COMP_SKIP:
    // Sync before next kz to avoid hazards on shared memory
    bar.sync 0;
    add.u32 r_kz, r_kz, 1;
    bra KZ_LOOP;
END_KZ:
    add.u32 r_ic, r_ic, 1;
    bra IC_LOOP;
END_IC:
