    setp.eq.u32 pbias0, rHasBias, 0;
    @pbias0 bra NO_BIAS;
    @!pActive bra NO_BIAS;
    cvt.u64.u32 addr_b, r_oc;
    shl.b64 addr_b, addr_b, 2;
    add.u64 addr_b, addr_b, bbase;
    ld.global.f32 bval, [addr_b];
    add.f32 acc, acc, bval;
    add.f32 acc1, acc1, bval;
NO_BIAS:
    // Store outputs if within Wout
    // y base index without wout: ((((n*Cout + oc)*Dout + dout)*Hout + hout)*Wout)
    mul.lo.u32 r_tmp3, r_n, rCout;
    add.u32    r_tmp3, r_tmp3, r_oc;
    mul.lo.u32 r_tmp3, r_tmp3, rDout;
    add.u32    r_tmp3, r_tmp3, r_dout;
    mul.lo.u32 r_tmp3, r_tmp3, rHout;
    add.u32    r_tmp3, r_tmp3, r_hout;
    mul.lo.u32 r_tmp3, r_tmp3, rWout;   // r_tmp3 = base_yw
    // store first output
    setp.ge.u32 pstore, r_wout0, rWout;
    @pstore bra SKIP_STORE0;
    add.u32    r_tmp2, r_tmp3, r_wout0;
    cvt.u64.u32 addr_y, r_tmp2;
    shl.b64 addr_y, addr_y, 2;
    add.u64 addr_y, addr_y, ybase;
    st.global.f32 [addr_y], acc;
SKIP_STORE0:
    // store second output
    setp.ge.u32 pstore1, r_wout1, rWout;
    @pstore1 bra END;
    add.u32    r_tmp2, r_tmp3, r_wout1;
    cvt.u64.u32 addr_y, r_tmp2;
    shl.b64 addr_y, addr_y, 2;
    add.u64 addr_y, addr_y, ybase;
    st.global.f32 [addr_y], acc1;
END:
    ret;
}
