            k = int(kernel_size[0])
        else:
            k = int(kernel_size)
        assert groups == 1, "groups != 1 not supported"
        assert stride == 1, "stride != 1 not supported"
        assert dilation == 1, "dilation != 1 not supported"
        assert padding >= 0, "padding must be non-negative"
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = k
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)
        self.has_bias = bool(bias)
        # Parameters: weight [out_channels, in_channels, K, K, K], optional bias [out_channels]
        self.weight = nn.Parameter(torch.empty(self.out_channels, self.in_channels, k, k, k))
        if self.has_bias:
